"""Build a local matched-timing report; all scientific counts come from reviewed records."""
import csv,hashlib,html,json,sys
from pathlib import Path
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
R=Path(sys.argv[1]).resolve();O=R.parent/'2026-10-19-answerable-abstention';read=lambda root,n:json.loads((root/n).read_text());h=lambda s:html.escape(str(s),quote=True)
P=read(R,'protocol.json');cases=read(R,'cases.json');rows=read(R,'artifacts/all-results.json')['rows'];review=read(R,'reviewed-judgments.json');g={x['trial_id']:x for x in review['rows']}
oldrows=read(O,'artifacts/all-results.json')['rows'];og={x['trial_id']:x for x in read(O,'reviewed-judgments.json')['rows']};oldsummary=read(O,'summary.json')
labels={'correct':'Correct answer','abstention':'Full coherent abstention','mixed':'Answer + uncertainty / caveat','broken':'Incoherent / repetitive','wrong':'Wrong answer','other':'Other'}
colors={'correct':'#367394','abstention':'#087765','mixed':'#8c668a','broken':'#b24c42','wrong':'#b17b2e','other':'#777c78'}
positive=[r for r in rows if r['added_gate'] is not None and r['added_gate']>0]
common=[1,2,4,8,16,24,32,48,64]
matched=[]
for scope,rs,gs in [('Output only',oldrows,og),('Prompt + output',rows,g)]:
 for a in common:
  xs=[r for r in rs if r['added_gate']==a];assert len(xs)==10
  matched.append({'scope':scope,'strength':a,'full_abstention':sum(gs[r['trial_id']]['false_abstention'] for r in xs),'mixed':sum(gs[r['trial_id']]['category']=='mixed' for r in xs),'coherent':sum(gs[r['trial_id']]['coherent'] for r in xs)})
(R/'matched-strength-counts.json').write_text(json.dumps(matched,indent=2)+'\n')
fig,axes=plt.subplots(1,3,figsize=(15,4.7),sharey=True)
for ax,metric,title in zip(axes,['full_abstention','mixed','coherent'],['Full coherent abstention','Answer + uncertainty / caveat','Coherent response']):
 for scope,offset,col,marker in [('Output only',-.35,'#8c668a','o'),('Prompt + output',.35,'#087765','D')]:
  xs=[x for x in matched if x['scope']==scope];ax.scatter([x['strength']+offset for x in xs],[x[metric] for x in xs],color=col,marker=marker,s=62,label=scope,edgecolor='white',linewidth=.6)
 ax.set_title(title);ax.set_xlabel('Added coefficient a');ax.set_xticks([1,8,16,24,32,48,64]);ax.set_ylim(-.4,10.6);ax.set_yticks([0,2,4,6,8,10]);ax.grid(alpha=.15);ax.spines[['top','right']].set_visible(False)
axes[0].set_ylabel('Questions out of 10');axes[1].legend(loc='upper center',bbox_to_anchor=(.5,-.22),ncol=2,frameon=False)
fig.suptitle('L19–T368: same ten questions, same coefficients, different token scope',fontsize=15);fig.subplots_adjust(top=.8,bottom=.28,wspace=.12);fig.savefig(R/'timing-comparison.png',dpi=170,facecolor='white');plt.close(fig)
fig,axes=plt.subplots(1,2,figsize=(14,6),sharey=True)
for ax,rs,gs,title in [(axes[0],oldrows,og,'Earlier: output only · common coarse grid'),(axes[1],positive,g,'New: full prompt + output · all tested values')]:
 for cat in colors:
  xs=[r for r in rs if r['added_gate'] is not None and r['added_gate']>0 and (title.startswith('New') or r['added_gate'] in common) and gs[r['trial_id']]['category']==cat]
  if xs:ax.scatter([r['added_gate'] for r in xs],[[c['id'] for c in cases].index(r['case_id']) for r in xs],color=colors[cat],s=47,label=labels[cat],edgecolor='white',linewidth=.5)
 ax.set_title(title,fontsize=11);ax.set_xlabel('Added coefficient a');ax.set_xlim(-1,66);ax.set_xticks([0,8,16,24,32,48,64]);ax.set_yticks(range(10),[c['id'] for c in cases]);ax.grid(alpha=.12);ax.spines[['top','right']].set_visible(False)
axes[0].invert_yaxis();handles,legend=axes[1].get_legend_handles_labels();fig.legend(handles,legend,loc='lower center',ncol=3,frameon=False,fontsize=9);fig.subplots_adjust(bottom=.2,top=.91,wspace=.1,left=.07,right=.98);fig.savefig(R/'all-outcomes.png',dpi=165,facecolor='white');plt.close(fig)
summary=[];cards=[];byold={r['trial_id']:r for r in oldrows}
for c in cases:
 xs=[r for r in positive if r['case_id']==c['id']];good=[r for r in xs if g[r['trial_id']]['false_abstention']];preferred=[r for r in good if not g[r['trial_id']]['additional_false_facts']]
 chosen=min(preferred or good,key=lambda r:r['added_gate']) if good else next((r for r in xs if r['trial_id']==review.get('representative_failures',{}).get(c['id'])),None)
 prev=next(x for x in oldsummary['per_case'] if x['id']==c['id']);before=byold.get(prev['selected_trial_id'])
 summary.append({'case_id':c['id'],'question':c['question'],'old_output_only_success':prev['coherent_false_abstention_found'],'new_all_token_success':bool(good),'new_successful_tested_strengths':[r['added_gate'] for r in good],'selected_trial_id':chosen['trial_id'] if chosen else None,'selected_strength':chosen['added_gate'] if chosen else None,'selected_answer':chosen['answer'] if chosen else None})
 def answerbox(title,answer,meta,cl=''):
  return f'<div class="answer {cl}"><span class="label">{h(title)}</span><blockquote>{h(answer)}</blockquote><p class="fine">{h(meta)}</p></div>'
 boxes=answerbox('Native · correct',c['prior_native_answer'],'Answer is supplied in the passage.')
 if before:boxes+=answerbox('Earlier output-only · +'+str(before['added_gate']),before['answer'],og[before['trial_id']]['notes'])
 if chosen:boxes+=answerbox('All tokens · +'+str(chosen['added_gate']),chosen['answer'],g[chosen['trial_id']]['notes'],'success' if good else 'failure')
 tested_values=", ".join(f"{r['added_gate']:g}" for r in sorted(xs,key=lambda r:r["added_gate"]))
 cards.append(f'<article class="example" id="case-{c["id"]}"><h3>{h(c["id"])} · {h(c["question"])}</h3><p class="fine">Reference: {h(c["reference_answer"])}. Full abstention found: {"yes" if good else "no"}.</p><div class="triple">{boxes}</div><p class="fine">All-token values tested: {h(tested_values)}. These are tested values, not proven minima.</p></article>')
success=sum(x['new_all_token_success'] for x in summary);oldsuccess=sum(x['old_output_only_success'] for x in summary)
full={'questions':10,'native_correct':10,'old_output_only_tuned_success_cases':oldsuccess,'all_token_tuned_success_cases':success,'positive_trials':len(positive),'controls':20,'common_grid_any_success':{scope:sum(any(gs[r['trial_id']]['false_abstention'] for r in rs if r['case_id']==c['id'] and r['added_gate'] in common) for c in cases) for scope,rs,gs in [('output_only',oldrows,og),('all_tokens',rows,g)]},'per_case':summary,'comparison_limit':'Per-question tuned searches have unequal total budgets. The common nine-value grid is the matched comparison. Ten selected questions, not a held-out benchmark rate.'}
(R/'summary.json').write_text(json.dumps(full,ensure_ascii=False,indent=2)+'\n')
fields=['trial_id','case_id','question','reference_answer','added_gate','answer','first_output_token_unchanged','category','coherent','explicit_abstention','substantive_answer','false_abstention','notes']
with (R/'all-responses.csv').open('w') as f:
 w=csv.DictWriter(f,fieldnames=fields);w.writeheader()
 for r in rows:w.writerow({k:r[k] if k in r else g[r['trial_id']].get(k) for k in fields})
tr=''.join(f'<tr><th><a href="#case-{x["case_id"]}">{x["case_id"]}</a></th><td>{h(x["question"])}</td><td>{"Yes" if x["old_output_only_success"] else "No"}</td><td>{"Yes" if x["new_all_token_success"] else "No"}</td><td>{h(", ".join(str(a) for a in x["new_successful_tested_strengths"]) or "—")}</td></tr>' for x in summary)
trials=''.join(f'<details class="trial" data-category="{g[r["trial_id"]]["category"]}" id="{r["trial_id"]}"><summary>{h(r["case_id"])} · {"Native" if r["added_gate"] is None else "+"+str(r["added_gate"])} · {h(labels[g[r["trial_id"]]["category"]])}</summary><blockquote>{h(r["answer"])}</blockquote><p class="fine">{h(g[r["trial_id"]]["notes"])} First token unchanged: {r["first_output_token_unchanged"]}. Edited prompt positions: {r["summary"]["processed_prompt_tokens"] if r["added_gate"] else 0}. Total actual edited positions: {r["summary"]["edited_positions"]}.</p></details>' for r in rows)
style='''*{box-sizing:border-box}body{margin:0;background:#faf8f1;color:#20363e;font:16px/1.65 system-ui,sans-serif}main{max-width:1320px;margin:auto;padding:40px 28px 80px}h1{font-size:clamp(32px,5vw,55px);line-height:1.1;letter-spacing:-.04em}h2{font-size:28px;margin-top:45px}h3{font-size:18px}.lead{font-size:20px;max-width:1000px}.fine{font-size:12px;color:#596d70}.label,.eyebrow{font-size:11px;text-transform:uppercase;letter-spacing:.08em;font-weight:750}.note{padding:22px 26px;background:#e8f0e4;border-left:4px solid #087765;margin:25px 0}.triple{display:grid;grid-template-columns:repeat(3,1fr);gap:13px}.answer{min-width:0;padding:18px;background:#fffefa;border:1px solid #d3dbd0;border-radius:9px}.success{background:#e8f1e5}.failure{background:#f8eee6}blockquote{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.8 ui-monospace,monospace;margin:14px 0}.example{padding:20px 0;border-bottom:1px solid #d6ddd1}img{width:100%;height:auto;display:block;border:1px solid #d4dad0;border-radius:7px}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px}td,th{padding:12px;text-align:left;border-bottom:1px solid #d5dcd1}thead{background:#e8ede4}a{color:#087765}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#1b3740;color:#fff;padding:22px;font-size:13px}details{padding:16px;border:1px solid #d6ddd1;background:#fffefa;border-radius:7px;margin:10px 0}summary{cursor:pointer;font-size:13px}.links,.toolbar{display:flex;flex-wrap:wrap;gap:15px;margin:20px 0;font-size:13px}button{padding:9px;background:white;border:1px solid #8eaaa0;color:#087765;border-radius:5px;cursor:pointer}@media(max-width:800px){main{padding:24px 16px}.triple{grid-template-columns:1fr}h1{font-size:34px}td,th{font-size:11px;padding:9px}}'''
intro=f'{success}/10 questions reached full coherent abstention with all-token steering, compared with {oldsuccess}/10 in the earlier output-only search.'
page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>All-token abstention steering · L19–T368</title><style>{style}</style></head><body><main><p class="eyebrow">Qwen3–4B · L19–T368 · 19 October 2026 · matched timing follow-up</p><h1>Can earlier steering prevent “answer + I don’t know”?</h1><p class="lead">Same ten answer-present questions, checkpoint, MOLT and additive intervention. This time steering runs during the entire prompt as well as every processed response token.</p><div class="note"><b>{h(intro)}</b><p>The target is a readable refusal without disclosing the answer. An answer followed by uncertainty fails this test. The answer is present, so a successful intervention induces false abstention.</p></div><p>All ten native answers were correct. All twenty native/zero controls reproduce their saved token sequences exactly. The all-token run tests {len(positive)} positive interventions. Success counts use separate per-question tuning; use the common-strength plots below for the matched comparison.</p><h2>What changed in timing?</h2><pre>Earlier: prompt untouched → first answer token native → steer processed output tokens
Now:     steer every prompt token → first answer token may change → continue steering output tokens

At layer 19, transform 368, for every eligible position:
z = current post-attention residual, standardized with released statistics
L(z) = ((z @ V_368) @ U_368) × output_std_19
native MLP output += a × L(z)
effective estimated gate = natural_gate(z) + a</pre><p>The positive coefficient is added to the estimated gate; it is not a fixed gate replacement. The formula matches the preceding output-only study. Every encoded input token is included: instruction, passage, question, chat markers and assistant prefix. During generation, each emitted token is edited when processed to predict the next token. EOS and the final capped token are not processed again. Native MLP retained, attention unfrozen, no donor or frozen clean trajectory. Label: “Onset of Refusal or Ignorance Statements”; all IDs zero-based.</p><h2>Same nine coefficients: matched comparison</h2><img src="timing-comparison.png" alt="Three scatter plots comparing full abstention, answer plus uncertainty, and coherence"><p class="fine">Each point counts ten questions. No connecting lines. Marker positions have a small horizontal offset for visibility. Common coefficients: 1, 2, 4, 8, 16, 24, 32, 48, 64. Extra all-token values and refinements appear in the next figure and full records.</p><p><b>At the same +16 coefficient:</b> output-only yields 0/10 full abstentions; all-token yields 6/10, with all ten responses still readable. Across the same nine-value grid, full abstention is found for 2/10 output-only cases and 7/10 all-token cases. The earlier 3/10 figure includes its finer per-question search.</p><h2>Results by question</h2><div class="scroll"><table><thead><tr><th>Case</th><th>Question</th><th>Earlier output-only full abstention found?</th><th>All-token full abstention found?</th><th>Successful tested all-token additions</th></tr></thead><tbody>{tr}</tbody></table></div><p class="fine">Success means coherent explicit withholding with no substantive answer. False passage-absence rationales are recorded separately. “Not found” is limited to this tested search.</p><h2>Read the baseline and steered answers</h2>{''.join(cards)}<h2>All tested outcomes</h2><img src="all-outcomes.png" alt="Categorical scatter plots of intervention outcomes for each question"><p class="fine">Left uses the nine common coefficients; right includes every all-token value tested. Every generation is saved, including repetition and failures.</p><h2>Interpretation and limits</h2><p>Editing the prompt can change both passage processing and the first answer decision. It also loses the earlier eel conversion in this tested search: output-only could withhold the eel answer, while prompt-plus-output still names eels or breaks down. This does not isolate a first-token mechanism or demonstrate that knowledge was erased. The ten questions are a fixed exploratory cohort, with one greedy generation per condition. Search is coarse-to-fine without assuming monotonicity; successful tested strengths are not proven minima. Complete answers were reviewed by Codex with conditions visible; no independent blinded grading or unrelated-transform control is included.</p><p>Thinking disabled, greedy batch one, KV cache, 96-new-token cap; BF16 native model, FP32 MOLT math. Checkpoints, exact prompts and immutable asset hashes are in the protocol. All input and processed output positions, source hashes, actual BF16 changes and replay controls are audited.</p><h2>Every complete response</h2><div class="toolbar"><button data-filter="all">All</button><button data-filter="abstention">Full abstention</button><button data-filter="mixed">Answer + uncertainty</button><button data-filter="broken">Incoherent</button></div>{trials}<div class="links"><a href="all-responses.csv">Responses + reviews CSV</a><a href="artifacts/all-results.json">Raw tokens + position traces</a><a href="verification.json">Verification</a><a href="reviewed-judgments.json">Reviews</a><a href="protocol.json">Protocol + pins</a><a href="cohort.json">Passages + provenance</a><a href="summary.json">Summary</a><a href="../2026-10-19-answerable-abstention/index.html">Earlier output-only report</a></div><p class="fine">Selected SQuAD2.0 text, CC BY-SA 4.0. GPU retained for follow-ups under the user’s instruction.</p></main><script>document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>document.querySelectorAll('.trial').forEach(x=>x.hidden=b.dataset.filter!=='all'&&x.dataset.category!==b.dataset.filter)))</script></body></html>'''
(R/'index.html').write_text(page);print(json.dumps({k:v for k,v in full.items() if k!='per_case'},indent=2))
